with deduped as (select * from (select *, row_number() over (partition by store_id, product_id order by quantity desc nulls last, id) as latest_rank from inventory) ranked where latest_rank = 1) select date_trunc('week', last_restock) as week_start, round(avg(quantity), 2) as avg_quantity, count(distinct product_id) as distinct_product_ids, count(*) as event_count, bit_and(quantity) as quantity_bit_and, approx_percentile(quantity, array(0.25, 0.5, 0.75)) as quantity_quartiles from deduped group by week_start having round(avg(quantity), 2) < 0 order by avg_quantity nulls last
